/** Existing form submission entry point. */
export async function processForm(fields, values, send) {
  const eligible = fields.filter(field => !field.disabled);
  const errors = {};
  for (const field of eligible) {
    const value = Object.hasOwn(values, field.name) ? values[field.name] : undefined;
    let error;
    if (field.required && (value === undefined || value === null || value === '')) {
      error = 'Required';
    } else if (field.validate) {
      error = await field.validate(value, values);
    }
    if (error) Object.defineProperty(errors, field.name, { value: error, enumerable: true });
  }
  if (Object.keys(errors).length) return { errors };
  return send(Object.fromEntries(eligible.map(field => [field.name,
    Object.hasOwn(values, field.name) ? values[field.name] : undefined])));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { processForm } from '../src/process-form.js';

test('inactive conditional field cannot validate, block or submit', async () => {
  const result = await processForm([
    { name: 'kind' },
    { name: 'company', enabledWhen: values => values.kind === 'business', required: true,
      validate() { assert.fail('inactive validator ran'); } },
  ], { kind: 'personal', company: '', unknown: 1 }, payload => payload);
  assert.deepEqual(result, { kind: 'personal' });
});

test('conditional field is recalculated once on each submission', async () => {
  let calls = 0;
  const fields = [{ name: 'company', required: true,
    enabledWhen(values) { calls++; return values.kind === 'business'; } }];
  assert.deepEqual(await processForm(fields, { kind: 'personal' }, x => x), {});
  assert.deepEqual(await processForm(fields, { kind: 'business', company: '' }, () => assert.fail('sent')),
    { errors: { company: 'Required' } });
  assert.deepEqual(await processForm(fields, { kind: 'business', company: 'Acme' }, x => x), { company: 'Acme' });
  assert.equal(calls, 3);
});

test('disabled wins over the conditional callback', async () => {
  assert.deepEqual(await processForm([{ name: 'old', disabled: true,
    enabledWhen() { assert.fail('disabled condition ran'); } }], { old: 1 }, x => x), {});
});

test('conditions, validators and payload use the same top-level submission snapshot', async () => {
  let release;
  let started;
  const entered = new Promise(resolve => { started = resolve; });
  const gate = new Promise(resolve => { release = resolve; });
  const values = { kind: 'business', company: 'Before' };
  let conditionSnapshot;
  let validatorSnapshot;
  const pending = processForm([
    { name: 'kind', validate: async (value, snapshot) => { validatorSnapshot = snapshot; started(); await gate; } },
    { name: 'company', enabledWhen(snapshot) { conditionSnapshot = snapshot; return snapshot.kind === 'business'; },
      validate(value, snapshot) { assert.equal(value, 'Before'); assert.equal(snapshot, validatorSnapshot); } },
  ], values, x => x);
  await entered;
  values.kind = 'personal'; values.company = 'After';
  release();
  assert.deepEqual(await pending, { kind: 'business', company: 'Before' });
  assert.equal(conditionSnapshot, validatorSnapshot);
  assert.notEqual(conditionSnapshot, values);
  assert.deepEqual(values, { kind: 'personal', company: 'After' });
});

test('conditional failures propagate with their original identity', async () => {
  const failure = new Error('condition failed');
  await assert.rejects(processForm([{ name: 'x', enabledWhen() { throw failure; } }], { x: 1 },
    () => assert.fail('sent')), error => error === failure);
});

test('conditional prototype-like names remain own payload keys', async () => {
  let calls = 0;
  const result = await processForm([{ name: '__proto__', enabledWhen() { calls++; return false; } }],
    { ['__proto__']: 'hidden' }, x => x);
  assert.equal(Object.hasOwn(result, '__proto__'), false);
  assert.equal(calls, 1);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { processForm } from '../src/process-form.js';

test('disabled validation never runs or blocks, and payload excludes disabled/unknown fields', async () => {
  let calls = 0;
  const result = await processForm([
    { name: 'name', required: true },
    { name: 'legacy', disabled: true, required: true, validate() { throw Error('must not run'); } },
  ], { name: 'Ada', legacy: 'secret', unknown: 'extra' }, payload => { calls++; assert.deepEqual(payload, { name: 'Ada' }); return 'sent'; });
  assert.equal(result, 'sent'); assert.equal(calls, 1);
});
test('zero false whitespace and empty arrays satisfy required', async () => {
  const values = { count: 0, consent: false, text: ' ', items: [] };
  const fields = Object.keys(values).map(name => ({ name, required: true }));
  assert.deepEqual(await processForm(fields, values, payload => payload), values);
});
test('all specified empty representations fail and skip custom validation', async () => {
  const values = { absent: undefined, nil: null, blank: '' };
  const fields = Object.keys(values).map(name => ({ name, required: true, validate() { assert.fail('required failure must short circuit this field'); } }));
  const result = await processForm(fields, values, () => assert.fail('invalid form sent'));
  assert.deepEqual(result, { errors: { absent: 'Required', nil: 'Required', blank: 'Required' } });
});
test('async validator preserves specific error and blocks send', async () => {
  const result = await processForm([{ name: 'name', validate: async () => 'Already taken' }], { name: 'Ada' }, () => assert.fail('invalid form sent'));
  assert.deepEqual(result, { errors: { name: 'Already taken' } });
});
test('send waits for custom validation and returns the send result without mutation', async () => {
  let release; const gate = new Promise(resolve => { release = resolve; }); let sent = 0;
  const fields = Object.freeze([Object.freeze({ name: 'value', validate: () => gate })]);
  const values = Object.freeze({ value: 1 });
  const pending = processForm(fields, values, async payload => { sent++; return { saved: payload.value }; });
  await Promise.resolve(); assert.equal(sent, 0); release(undefined);
  assert.deepEqual(await pending, { saved: 1 }); assert.equal(sent, 1);
});
test('validator and transport rejections propagate', async () => {
  const failure = Error('offline');
  await assert.rejects(processForm([{ name: 'x', validate: async () => { throw failure; } }], { x: 1 }, () => assert.fail('sent')), error => error === failure);
  await assert.rejects(processForm([{ name: 'x' }], { x: 1 }, async () => { throw failure; }), error => error === failure);
});
test('prototype-like names remain own error and payload keys', async () => {
  const fields = [{ name: '__proto__', required: true }];
  const result = await processForm(fields, {}, () => assert.fail('sent'));
  assert.equal(Object.hasOwn(result.errors, '__proto__'), true); assert.equal(result.errors.__proto__, 'Required');
  const payload = await processForm(fields, { ['__proto__']: 'value' }, payload => payload);
  assert.equal(Object.hasOwn(payload, '__proto__'), true); assert.equal(payload.__proto__, 'value');
});

